def function(named_arg, *args):
    print(named_arg)
    print(args) # args 是一个元组

function(1, 2, 3, 4, 5)

def my_func(x, y=7, *args, **kwargs):
    print(args) # (4, 5, 6)
    print(kwargs) # kwargs 是字典 {'a': 7, 'b': 8}

my_func(2, 3, 4, 5, 6, a=7, b=8)

# 输出
# (4, 5, 6)
# {'a': 7, 'b': 8}

